(()=>{'use strict';
const $=id=>document.getElementById(id),form=$('viewing'),KEY='immobrain-viewings-v1',DRAFT='immobrain-viewing-draft-v1',PRESETS='immobrain-viewing-prices-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(n),num=n=>Number.isFinite(Number(n))&&Number(n)>=0?Number(n):0;
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}}
function write(key,value){try{localStorage.setItem(key,JSON.stringify(value));if(key===KEY)window.dispatchEvent(new Event('immobrain-calendar-changed'));return true}catch{$('message').textContent='Speicherung fehlgeschlagen. Bitte Browserspeicher prüfen; Eingaben bleiben geöffnet.';return false}}
let rows=[],active=null,dirty=false;
function blank(){const prices=read(PRESETS,{});return {fields:{reserve:15},rows:ViewingData.costs.map(([group,label,unit,actions],i)=>({id:'p'+i,group,label,unit,actions,action:0,qty:0,price:0,prices:{}})),checks:{},notes:{}}}
function collect(){return {fields:Object.fromEntries([...form.querySelectorAll('[name]')].map(x=>[x.name,x.value])),rows:JSON.parse(JSON.stringify(rows)),checks:Object.fromEntries([...document.querySelectorAll('[data-check]')].map(x=>[x.dataset.check,x.value])),notes:Object.fromEntries([...document.querySelectorAll('[data-note]')].map(x=>[x.dataset.note,x.value]))}}
function total(items,reserve){let base=0,missing=0;for(const r of items){if(Number(r.action)<=0)continue;const qty=num(r.qty),price=num(r.price);if(!qty||!price)missing++;base+=qty*price}base=Math.round(base*100)/100;const buffer=Math.round(base*num(reserve))/100;return {base,buffer,total:base+buffer,missing}}
function update(){const t=total(rows,form.elements.namedItem('reserve').value);$('base').textContent=money(t.base);$('buffer').textContent=money(t.buffer);$('total').textContent=money(t.total);$('missing').textContent=t.missing?`${t.missing} ausgewählte Position(en) ohne Menge oder Preis – Summe unvollständig.`:'Nur erfasste Positionen berücksichtigt.';for(const r of rows){const out=document.querySelector('[data-output="'+r.id+'"]');if(out)out.textContent=money(Number(r.action)>0?num(r.qty)*num(r.price):0)}}
function changed(){dirty=true;$('message').textContent='Ungespeicherte Änderungen';update();write(DRAFT,{active,data:collect()})}
function renderRows(){let last='';$('costs').innerHTML=rows.map(r=>{const heading=r.group!==last?`<h3 class="group-title">${esc(r.group)}</h3>`:'';last=r.group;return heading+`<div class="cost-row" data-row="${esc(r.id)}"><div>${r.custom?`<label>Eigene Position<input data-field="label" value="${esc(r.label)}" required maxlength="150"></label><button type="button" data-remove="${esc(r.id)}">Entfernen</button>`:`<strong>${esc(r.label)}</strong>`}<small>${esc(r.unit)}</small></div><label>Maßnahme<select data-field="action">${r.actions.map((a,i)=>`<option value="${i}" ${Number(r.action)===i?'selected':''}>${esc(a)}</option>`).join('')}</select></label><label>Menge<input data-field="qty" type="number" min="0" max="1000000" step="0.01" value="${esc(r.qty)}"></label><label>€ / ${esc(r.unit)}<input data-field="price" type="number" min="0" max="100000000" step="0.01" value="${esc(r.price)}"></label><output data-output="${esc(r.id)}"></output></div>`}).join('');update()}
function load(data,id=null){active=id;rows=Array.isArray(data.rows)?data.rows:blank().rows;form.reset();renderFavorites(data.fields?.listingRef||'');for(const [key,val]of Object.entries(data.fields||{})){const f=form.elements.namedItem(key);if(f)f.value=val}renderRows();$('checks').innerHTML=ViewingData.checks.map(([title,items],i)=>`<section class="panel"><h2>${esc(title)}</h2>${items.map((label,j)=>{const key=i+'-'+j;return `<div class="check-row"><label for="check-${key}">${esc(label)}</label><select id="check-${key}" data-check="${key}">${['Noch nicht geprüft','In Ordnung / vorhanden','Prüfbedarf','Mangel / nicht vorhanden','Nicht zutreffend'].map(o=>`<option ${data.checks?.[key]===o?'selected':''}>${o}</option>`).join('')}</select></div>`}).join('')}<label>Feststellungen und offene Fragen<textarea data-note="${i}" maxlength="10000">${esc(data.notes?.[i]||'')}</textarea></label></section>`).join('');dirty=false;update();$('message').textContent=id?'Gespeicherte Besichtigung geöffnet.':'Neue Besichtigung.'}
function saved(){const list=read(KEY,[]);return Array.isArray(list)?list:[]}
function renderSaved(){$('saved').innerHTML=saved().map(x=>`<article><strong>${esc(x.name)}</strong><span>${money(total(x.data.rows,num(x.data.fields.reserve)).total)}</span><button type="button" data-open="${esc(x.id)}">Bearbeiten</button><button type="button" data-delete="${esc(x.id)}">Löschen</button></article>`).join('')||'<p>Noch keine Besichtigungen gespeichert.</p>'}
$('costs').addEventListener('input',e=>{const root=e.target.closest('[data-row]');if(!root||!e.target.dataset.field)return;const r=rows.find(x=>x.id===root.dataset.row),key=e.target.dataset.field;if(!r)return;if(key==='action'){r.prices||={};r.prices[r.action]=num(r.price);r.action=Number(e.target.value);r.price=priceFor(r,r.action,read(PRESETS,{}));root.querySelector('[data-field="price"]').value=r.price}else{r[key]=key==='label'?e.target.value:num(e.target.value);if(key==='price'){r.prices||={};r.prices[r.action]=r.price}}});
form.addEventListener('input',changed);form.addEventListener('change',changed);
$('costs').addEventListener('click',e=>{const id=e.target.dataset.remove;if(!id)return;rows=rows.filter(x=>x.id!==id);renderRows();changed()});
$('add').onclick=()=>{rows.push({id:'c'+crypto.randomUUID(),group:'Eigene Positionen',label:'Neue Position',unit:'pauschal',actions:['Keine Arbeit','Ausführen'],action:1,qty:1,price:0,prices:{},custom:true});renderRows();changed()};
function priceFor(row,action,templates){return Object.hasOwn(row.prices||{},action)?num(row.prices[action]):num(templates[row.id]?.[action])}
function renderPrices(){const prices=read(PRESETS,{});let last='';$('price-fields').innerHTML=ViewingData.costs.map(([group,label,unit,actions],i)=>{const heading=last!==group?`<h3 class="group-title">${esc(group)}</h3>`:'';last=group;return heading+`<div class="price-template"><strong>${esc(label)}</strong><div class="fields">${actions.slice(1).map((action,j)=>`<label>${esc(action)} · € / ${esc(unit)}<input data-price-id="p${i}" data-price-action="${j+1}" type="number" min="0" max="100000000" step="0.01" placeholder="Noch kein Standardpreis" value="${prices['p'+i]?.[j+1]??''}"></label>`).join('')}</div></div>`}).join('')}
$('price-form').onsubmit=e=>{e.preventDefault();if(!$('price-form').reportValidity())return;const prices={};for(const field of $('price-fields').querySelectorAll('[data-price-id]')){if(field.value==='')continue;(prices[field.dataset.priceId]||={})[field.dataset.priceAction]=num(field.value)}if(write(PRESETS,prices)){$('price-message').textContent='Standardpreise gespeichert. Sie werden bei der Auswahl einer Maßnahme automatisch übernommen. Bereits eingetragene Objektpreise bleiben erhalten.'}else $('price-message').textContent='Standardpreise konnten nicht gespeichert werden.'};
$('apply-prices').onclick=()=>{const prices=read(PRESETS,{});let count=0;for(const r of rows){const price=num(prices[r.id]?.[r.action]);if(!r.custom&&Number(r.action)>0&&!num(r.price)&&price>0){r.price=price;r.prices||={};r.prices[r.action]=price;count++}}renderRows();if(count)changed();$('message').textContent=count?`${count} fehlende Preise aus Vorlage übernommen. Besichtigung zum Übernehmen speichern.`:'Keine fehlenden Preise mit passender Vorlage gefunden. Bereits eingetragene Preise bleiben unverändert.'};
$('presets').onclick=()=>{const prices=read(PRESETS,{});for(const r of rows.filter(r=>!r.custom)){prices[r.id]={...prices[r.id],...r.prices};if(Number(r.action)>0)prices[r.id][r.action]=num(r.price)}if(write(PRESETS,prices)){renderPrices();$('message').textContent='Objektpreise als Standardvorlage gespeichert.'}};
renderPrices();
form.onsubmit=e=>{e.preventDefault();if(!form.reportValidity())return;const data=collect(),name=data.fields.address.trim();if(!name)return;const id=active||crypto.randomUUID(),list=saved(),entry={id,name,data,updatedAt:new Date().toISOString()},i=list.findIndex(x=>x.id===id);if(i>=0)list[i]=entry;else list.push(entry);if(!write(KEY,list))return;active=id;dirty=false;setLink(id);const linked=data.fields.listingRef;if(linked&&data.fields.date){const day=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Berlin',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());if(data.fields.date<=day){const state=read('immobrain-listing-status-v1',{});if(state[linked]&&state[linked].status!=='angebot'){state[linked].status='besichtigt';state[linked].statusManual=false;write('immobrain-listing-status-v1',state)}}}try{localStorage.removeItem(DRAFT)}catch{}renderSaved();$('message').textContent='Besichtigung gespeichert.'};
$('saved').onclick=e=>{const id=e.target.dataset.open||e.target.dataset.delete;if(!id)return;if(e.target.dataset.open){if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen?'))return;const entry=saved().find(x=>x.id===id);if(entry){load(entry.data,id);setLink(id);write(DRAFT,{active,data:collect()})}}else if(confirm('Besichtigung wirklich löschen?')){if(write(KEY,saved().filter(x=>x.id!==id))){if(active===id){active=null;dirty=true;write(DRAFT,{active,data:collect()})}renderSaved();$('message').textContent='Besichtigung gelöscht.'}}};
$('new').onclick=()=>{if(dirty&&!confirm('Ungespeicherte Änderungen verwerfen?'))return;load(blank());setLink(null);write(DRAFT,{active,data:collect()})};
function favorites(){const state=read('immobrain-listing-status-v1',{});return Object.entries(state).filter(([,v])=>v?.favorite&&v.snapshot).map(([key,v])=>{const x=v.snapshot,a={...x,...v.address};return {key,x,label:[a.street,a.zipcode,a.city,x.title].filter(Boolean).join(' · ')}})}
function renderFavorites(selected=''){const items=favorites();$('listing-ref').innerHTML='<option value="">Manuell eingeben · ohne Zuordnung</option>'+items.map(x=>`<option value="${esc(x.key)}">${esc(x.label)}</option>`).join('');if(selected&&!items.some(x=>x.key===selected)){$('listing-ref').innerHTML+=`<option value="${esc(selected)}">Bisherige Objektzuordnung (nicht mehr favorisiert)</option>`}$('listing-ref').value=selected}
$('listing-ref').onchange=()=>{const selected=favorites().find(x=>x.key===$('listing-ref').value);if(!selected){$('listing-message').textContent='Manuelle Eingabe. Vorhandene Objektdaten bleiben erhalten.';return}const next={address:selected.label};const conflicts=Object.entries(next).some(([key,val])=>val!=null&&form.elements.namedItem(key).value&&String(val)!==form.elements.namedItem(key).value);const replace=!conflicts||confirm('Vorhandene Adresse / Objektname mit den Angaben des gewählten Objekts ersetzen?');for(const [key,val]of Object.entries(next)){const field=form.elements.namedItem(key);if(val!=null&&(replace||!field.value))field.value=val}$('listing-message').textContent='Mit favorisiertem Objekt verknüpft. Termin und Ansprechpartner kannst du ergänzen.';changed()};
function setLink(id){const url=new URL(location.href);if(id)url.searchParams.set('viewing',id);else url.searchParams.delete('viewing');url.searchParams.delete('listing');history.replaceState(null,'',url.pathname+url.search+url.hash)}
const draft=read(DRAFT,null);load(draft?.data||blank(),draft?.active||null);if(draft?.data){dirty=true;$('message').textContent='Letzter Entwurf wiederhergestellt.'}renderSaved();
const params=new URLSearchParams(location.search),requested=params.get('viewing'),listing=params.get('listing');if(requested){const entry=saved().find(x=>x.id===requested);if(!entry)$('message').textContent='Diese Besichtigung wurde nicht gefunden.';else if(!dirty||confirm('Gespeicherte Besichtigung öffnen und den aktuellen Entwurf verlassen?'))load(entry.data,entry.id)}else if(listing&&(!dirty||confirm('Neue Besichtigung für dieses Objekt starten und den aktuellen Entwurf verlassen?'))){load(blank());renderFavorites(listing);$('listing-ref').onchange();write(DRAFT,{active,data:collect()})}
})();
